export type LiquidityWithdrawal = Node & {
  __typename?: 'LiquidityWithdrawal';
  amount: Scalars['BigFloat']['output'];
  asset: ChainflipAsset;
  /** Reads a single `Block` that is related to this `LiquidityWithdrawal`. */
  blockByBlockId: Block;
  blockId: Scalars['Int']['output'];
  /** Reads a single `Broadcast` that is related to this `LiquidityWithdrawal`. */
  broadcastByBroadcastId?: Maybe<Broadcast>;
  broadcastId?: Maybe<Scalars['Int']['output']>;
  chain: ChainflipChain;
  /** Reads a single `Event` that is related to this `LiquidityWithdrawal`. */
  eventByEventId: Event;
  eventId: Scalars['BigInt']['output'];
  fee: Scalars['BigFloat']['output'];
  feeUsd?: Maybe<Scalars['BigFloat']['output']>;
  id: Scalars['Int']['output'];
  /** Reads a single `LiquidityProvider` that is related to this `LiquidityWithdrawal`. */
  liquidityProviderByLiquidityProviderId: LiquidityProvider;
  liquidityProviderId: Scalars['Int']['output'];
  nativeEgressId: Scalars['BigInt']['output'];
  /** A globally unique identifier. Can be used in various places throughout the system to identify this single value. */
  nodeId: Scalars['ID']['output'];
  valueUsd: Scalars['BigFloat']['output'];
  withdrawalAddress: Scalars['String']['output'];
};

export type LiquidityWithdrawalAggregates = {
  __typename?: 'LiquidityWithdrawalAggregates';
  /** Mean average aggregates across the matching connection (ignoring before/after/first/last/offset) */
  average?: Maybe<LiquidityWithdrawalAverageAggregates>;
  /** Distinct count aggregates across the matching connection (ignoring before/after/first/last/offset) */
  distinctCount?: Maybe<LiquidityWithdrawalDistinctCountAggregates>;
  keys?: Maybe<Array<Scalars['String']['output']>>;
  /** Maximum aggregates across the matching connection (ignoring before/after/first/last/offset) */
  max?: Maybe<LiquidityWithdrawalMaxAggregates>;
  /** Minimum aggregates across the matching connection (ignoring before/after/first/last/offset) */
  min?: Maybe<LiquidityWithdrawalMinAggregates>;
  /** Population standard deviation aggregates across the matching connection (ignoring before/after/first/last/offset) */
  stddevPopulation?: Maybe<LiquidityWithdrawalStddevPopulationAggregates>;
  /** Sample standard deviation aggregates across the matching connection (ignoring before/after/first/last/offset) */
  stddevSample?: Maybe<LiquidityWithdrawalStddevSampleAggregates>;
  /** Sum aggregates across the matching connection (ignoring before/after/first/last/offset) */
  sum?: Maybe<LiquidityWithdrawalSumAggregates>;
  /** Population variance aggregates across the matching connection (ignoring before/after/first/last/offset) */
  variancePopulation?: Maybe<LiquidityWithdrawalVariancePopulationAggregates>;
  /** Sample variance aggregates across the matching connection (ignoring before/after/first/last/offset) */
  varianceSample?: Maybe<LiquidityWithdrawalVarianceSampleAggregates>;
};

/** A filter to be used against aggregates of `LiquidityWithdrawal` object types. */
export type LiquidityWithdrawalAggregatesFilter = {
  /** Mean average aggregate over matching `LiquidityWithdrawal` objects. */
  average?: InputMaybe<LiquidityWithdrawalAverageAggregateFilter>;
  /** Distinct count aggregate over matching `LiquidityWithdrawal` objects. */
  distinctCount?: InputMaybe<LiquidityWithdrawalDistinctCountAggregateFilter>;
  /** A filter that must pass for the relevant `LiquidityWithdrawal` object to be included within the aggregate. */
  filter?: InputMaybe<LiquidityWithdrawalFilter>;
  /** Maximum aggregate over matching `LiquidityWithdrawal` objects. */
  max?: InputMaybe<LiquidityWithdrawalMaxAggregateFilter>;
  /** Minimum aggregate over matching `LiquidityWithdrawal` objects. */
  min?: InputMaybe<LiquidityWithdrawalMinAggregateFilter>;
  /** Population standard deviation aggregate over matching `LiquidityWithdrawal` objects. */
  stddevPopulation?: InputMaybe<LiquidityWithdrawalStddevPopulationAggregateFilter>;
  /** Sample standard deviation aggregate over matching `LiquidityWithdrawal` objects. */
  stddevSample?: InputMaybe<LiquidityWithdrawalStddevSampleAggregateFilter>;
  /** Sum aggregate over matching `LiquidityWithdrawal` objects. */
  sum?: InputMaybe<LiquidityWithdrawalSumAggregateFilter>;
  /** Population variance aggregate over matching `LiquidityWithdrawal` objects. */
  variancePopulation?: InputMaybe<LiquidityWithdrawalVariancePopulationAggregateFilter>;
  /** Sample variance aggregate over matching `LiquidityWithdrawal` objects. */
  varianceSample?: InputMaybe<LiquidityWithdrawalVarianceSampleAggregateFilter>;
};

