/** A filter to be used against `Operator` object types. All fields are combined with a logical ‘and.’ */
export type OperatorFilter = {
  /** Filter by the object’s `accountByAccountId` relation. */
  accountByAccountId?: InputMaybe<AccountFilter>;
  /** Filter by the object’s `accountId` field. */
  accountId?: InputMaybe<IntFilter>;
  /** Checks for all expressions in this list. */
  and?: InputMaybe<Array<OperatorFilter>>;
  /** Filter by the object’s `delegationActivitiesByOperatorId` relation. */
  delegationActivitiesByOperatorId?: InputMaybe<OperatorToManyDelegationActivityFilter>;
  /** Some related `delegationActivitiesByOperatorId` exist. */
  delegationActivitiesByOperatorIdExist?: InputMaybe<Scalars['Boolean']['input']>;
  /** Filter by the object’s `id` field. */
  id?: InputMaybe<IntFilter>;
  /** Negates the expression. */
  not?: InputMaybe<OperatorFilter>;
  /** Filter by the object’s `operatorActionsByOperatorId` relation. */
  operatorActionsByOperatorId?: InputMaybe<OperatorToManyOperatorActionFilter>;
  /** Some related `operatorActionsByOperatorId` exist. */
  operatorActionsByOperatorIdExist?: InputMaybe<Scalars['Boolean']['input']>;
  /** Filter by the object’s `operatorEpochDelegationApiesByOperatorId` relation. */
  operatorEpochDelegationApiesByOperatorId?: InputMaybe<OperatorToManyOperatorEpochDelegationApyFilter>;
  /** Some related `operatorEpochDelegationApiesByOperatorId` exist. */
  operatorEpochDelegationApiesByOperatorIdExist?: InputMaybe<Scalars['Boolean']['input']>;
  /** Filter by the object’s `operatorEpochesByOperatorId` relation. */
  operatorEpochesByOperatorId?: InputMaybe<OperatorToManyOperatorEpochFilter>;
  /** Some related `operatorEpochesByOperatorId` exist. */
  operatorEpochesByOperatorIdExist?: InputMaybe<Scalars['Boolean']['input']>;
  /** Filter by the object’s `operatorValidatorLinksByOperatorId` relation. */
  operatorValidatorLinksByOperatorId?: InputMaybe<OperatorToManyOperatorValidatorLinkFilter>;
  /** Some related `operatorValidatorLinksByOperatorId` exist. */
  operatorValidatorLinksByOperatorIdExist?: InputMaybe<Scalars['Boolean']['input']>;
  /** Checks for any expressions in this list. */
  or?: InputMaybe<Array<OperatorFilter>>;
  /** Filter by the object’s `validatorsByOperatorId` relation. */
  validatorsByOperatorId?: InputMaybe<OperatorToManyValidatorFilter>;
  /** Some related `validatorsByOperatorId` exist. */
  validatorsByOperatorIdExist?: InputMaybe<Scalars['Boolean']['input']>;
};

